// Hex colors are stored so every display element can be customized separately.
typedef struct {
  uint32_t version;
  int32_t clock_layout;       // 0 = stacked; 1 = single-line
  int32_t clock_size;         // 50..100, default 72
  int32_t show_ampm;
  int32_t battery_enabled;
  int32_t battery_position;   // 0 = top-right; 1 = bottom-right
  int32_t battery_icon_visible;
  int32_t battery_percent_visible;
  int32_t battery_icon_size;  // 30..100, default 40
  int32_t battery_text_size;  // 30..100, default 50
  int32_t background_color;
  int32_t hours_color;
  int32_t minutes_color;
  int32_t ampm_color;
  int32_t accent_color;
  int32_t date_color;
  int32_t battery_icon_color;
  int32_t battery_text_color;
  // Append only: preserve the v1 persistent struct's field order.
  int32_t accent_width;       // 8..120, default 29 pixels
  int32_t weekday_size;       // 10..24 pixels, default 14
  int32_t date_size;          // 10..24 pixels, default 14
  int32_t mirror_layout;      // 0=left clock / right battery, 1=opposite
} FaceSettings;

static Window *s_window;
static Layer *s_canvas;
static FaceSettings s_settings;
static BatteryChargeState s_battery;
static char s_hours[4];
static char s_minutes[4];
static char s_single[8];
static char s_weekday[8];
static char s_monthday[16];
static char s_ampm[4];

static int clamp_int(int value, int minval, int maxval) {
  if (value < minval) return minval;
  if (value > maxval) return maxval;
  return value;
}

static void defaults(void) {
  memset(&s_settings, 0, sizeof(s_settings));
  s_settings.version = SETTINGS_VERSION;
  s_settings.clock_layout = 0;
  s_settings.clock_size = 72;
  s_settings.show_ampm = 1;
  s_settings.battery_enabled = 1;
  s_settings.battery_position = 1;
  s_settings.battery_icon_visible = 1;
  s_settings.battery_percent_visible = 1;
  s_settings.battery_icon_size = 40;
  s_settings.battery_text_size = 50;
  s_settings.background_color = 0x000000;
  s_settings.hours_color = 0xFFFFFF;
  s_settings.minutes_color = 0xFFFFFF;
  s_settings.ampm_color = 0xAAAAAA;
  s_settings.accent_color = 0x55FFAA; // nearest Pebble-compatible mint
  s_settings.date_color = 0xFFFFFF;
  s_settings.battery_icon_color = 0x55FFAA;
  s_settings.battery_text_color = 0xFFFFFF;
  s_settings.accent_width = 29;
  s_settings.weekday_size = 14;
  s_settings.date_size = 14;
  s_settings.mirror_layout = 0;
}

static void load_settings(void) {
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 010 settings load begin");
  defaults();
  // Read either the original v1 record or the appended-field v2 record.
  // New fields in 'restored' start with defaults for existing installations.
  if (!persist_exists(SETTINGS_KEY)) return;
  const int stored_size = persist_get_size(SETTINGS_KEY);
  const int old_size = sizeof(FaceSettings) - 4 * sizeof(int32_t);
  if (stored_size != old_size && stored_size != (int)sizeof(FaceSettings)) return;
  FaceSettings restored = s_settings;
  if (persist_read_data(SETTINGS_KEY, &restored, stored_size) != stored_size) return;
  if (!((stored_size == old_size && restored.version == 1) ||
        (stored_size == (int)sizeof(FaceSettings) && restored.version == SETTINGS_VERSION))) return;
  restored.version = SETTINGS_VERSION;
  s_settings = restored;
  s_settings.clock_layout = clamp_int(s_settings.clock_layout, 0, 1);
  s_settings.clock_size = clamp_int(s_settings.clock_size, 50, 100);
  s_settings.show_ampm = clamp_int(s_settings.show_ampm, 0, 1);
  s_settings.battery_enabled = clamp_int(s_settings.battery_enabled, 0, 1);
  s_settings.battery_position = clamp_int(s_settings.battery_position, 0, 1);
  s_settings.battery_icon_visible = clamp_int(s_settings.battery_icon_visible, 0, 1);
  s_settings.battery_percent_visible = clamp_int(s_settings.battery_percent_visible, 0, 1);
  s_settings.battery_icon_size = clamp_int(s_settings.battery_icon_size, 30, 100);
  s_settings.battery_text_size = clamp_int(s_settings.battery_text_size, 30, 100);
  s_settings.accent_width = clamp_int(s_settings.accent_width, 8, 120);
  s_settings.weekday_size = clamp_int(s_settings.weekday_size, 10, 24);
  s_settings.date_size = clamp_int(s_settings.date_size, 10, 24);
  s_settings.mirror_layout = clamp_int(s_settings.mirror_layout, 0, 1);
}

static GColor color(int32_t hex) { return GColorFromHEX((uint32_t)hex); }

// Each row is rendered as a few runs of Pebble's four-channel colors.
// The masks retain antialiased contours without runtime fonts or floating point.
static int clock_glyph_width(const SmoothGlyph *glyph, int px_height) {
  return ((int)glyph->width * px_height + glyph->height / 2) / glyph->height;
}

static int clock_digits_width(const char *digits, bool heavy, int px_height) {
  const SmoothGlyph *glyphs = heavy ? k_smooth_bold_glyphs : k_smooth_light_glyphs;
  int total = 0;
  for (const char *p = digits; *p; ++p) {
    if (*p < '0' || *p > '9') continue;
    if (total) total += 2;
    total += clock_glyph_width(&glyphs[*p - '0'], px_height);
  }
  return total;
}

static uint8_t alpha_at(const uint8_t *data, const SmoothGlyph *g, int sx, int sy) {
  sx = clamp_int(sx,0,g->width-1);
  sy = clamp_int(sy,0,g->height-1);
  uint32_t index = g->offset + (uint32_t)sy*g->width + sx;
  return (data[index >> 2] >> (6 - ((index & 3) << 1))) & 3;
}

// Bilinear alpha lookup with 8-bit fractions and only fixed-point arithmetic.
static uint8_t sample_alpha(const uint8_t *data, const SmoothGlyph *g,
                            int px, int py, int dest_w, int dest_h) {
  if (dest_w <= 0 || dest_h <= 0) return 0;
  int fx = (((2*px+1)*g->width*128)/dest_w)-128;
  int fy = (((2*py+1)*g->height*128)/dest_h)-128;
  if (fx < 0) fx=0;
  if (fy < 0) fy=0;
  int sx=fx>>8,sy=fy>>8,dx=fx&255,dy=fy&255;
  uint32_t upper=(uint32_t)alpha_at(data,g,sx,sy)*(256-dx)
                 +(uint32_t)alpha_at(data,g,sx+1,sy)*dx;
  uint32_t lower=(uint32_t)alpha_at(data,g,sx,sy+1)*(256-dx)
                 +(uint32_t)alpha_at(data,g,sx+1,sy+1)*dx;
  return (uint8_t)((upper*(256-dy)+lower*dy+32768)/65536);
}

static GColor smooth_color(int32_t fg, int32_t bg, int a) {
  int r=((((fg>>16)&255)*a)+(((bg>>16)&255)*(3-a))+1)/3;
  int g=((((fg>>8)&255)*a)+(((bg>>8)&255)*(3-a))+1)/3;
  int b=(((fg&255)*a)+((bg&255)*(3-a))+1)/3;
  return GColorFromHEX(((uint32_t)r<<16)|((uint32_t)g<<8)|(uint32_t)b);
}

static void draw_smooth_digit(GContext *ctx, const SmoothGlyph *g,
                              const uint8_t *data, int x, int y, int w, int h,
                              const GColor palette[4]) {
  if (w<=0 || h<=0) return;
  for(int iy=0;iy<h;++iy) {
    int start=0;
    GColor current=palette[sample_alpha(data,g,0,iy,w,h)];
    for(int ix=1;ix<=w;++ix) {
      GColor next=ix<w?palette[sample_alpha(data,g,ix,iy,w,h)]:palette[0];
      if(ix==w || !gcolor_equal(next,current)) {
        if(!gcolor_equal(current,palette[0]) && ix>start) {
          graphics_context_set_fill_color(ctx,current);
          graphics_fill_rect(ctx,GRect(x+start,y+iy,ix-start,1),0,GCornerNone);
        }
        current=next;
        start=ix;
      }
    }
  }
}

static int draw_clock_digits(GContext *ctx, const char *digits, bool heavy,
                             int x, int y, int px_height, int32_t hex,
                             int fit_width) {
  const SmoothGlyph *glyphs=heavy?k_smooth_bold_glyphs:k_smooth_light_glyphs;
  const uint8_t *data=heavy?k_smooth_bold_alpha:k_smooth_light_alpha;
  const int natural=clock_digits_width(digits,heavy,px_height);
  if(natural<=0) return 0;
  const int result=fit_width>0?fit_width:natural;
  GColor palette[4];
  for(int i=0;i<4;++i)palette[i]=smooth_color(hex,s_settings.background_color,i);
  int cursor=0;
  for(const char *p=digits;*p;++p) {
    if(*p<'0'||*p>'9') continue;
    const SmoothGlyph *glyph=&glyphs[*p-'0'];
    const int gw=clock_glyph_width(glyph,px_height);
    const int left=x+cursor*result/natural;
    const int right=x+(cursor+gw)*result/natural;
    draw_smooth_digit(ctx,glyph,data,left,y,right-left,px_height,palette);
    cursor+=gw;
    if(p[1]>='0'&&p[1]<='9')cursor+=2;
  }
  return result;
}


// Draw any uppercase day/date string using the same 4-level antialiasing as
// the main clock. Pixel heights follow the user slider at *every* step.
static int small_char_index(char c) {
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'A' && c <= 'Z') return 10 + c - 'A';
  return -1;
}
static int small_text_width(const char *text, int h) {
  int width=0;
  for(const char *p=text; *p; ++p) {
    if(p!=text) width+=1;
    int g=small_char_index(*p);
    width+=g<0?h/3:clock_glyph_width(&k_small_glyphs[g],h);
  }
  return width;
}
static void draw_small_text(GContext *ctx,const char *text,int x,int y,
                            int h,int visible_width,int32_t hex) {
  if (!text || h<=0 || visible_width<=0) return;
  const int natural=small_text_width(text,h);
  if(natural<=0) return;
  GColor palette[4];
  for(int i=0;i<4;++i) palette[i]=smooth_color(hex,s_settings.background_color,i);
  int cursor=0;
  for(const char *p=text; *p; ++p) {
    const int index=small_char_index(*p);
    int glyphw=index<0?h/3:clock_glyph_width(&k_small_glyphs[index],h);
    if(index>=0) {
      const int left=x+cursor*visible_width/natural;
      const int right=x+(cursor+glyphw)*visible_width/natural;
      draw_smooth_digit(ctx,&k_small_glyphs[index],k_small_alpha,
                        left,y,right-left,h,palette);
    }
    cursor+=glyphw;
    if(p[1])cursor++;
  }
}

static void draw_date_row(GContext *ctx,int width,int height) {
  const int max_line_width=width-24;
  const bool mirrored=s_settings.mirror_layout!=0;
  const bool battery_bottom=s_settings.battery_enabled &&
      s_settings.battery_position==1 &&
      (s_settings.battery_icon_visible || s_settings.battery_percent_visible);
  // When the battery occupies the bottom corner reserve space opposite it.
  const int available=battery_bottom ? max_line_width-42 : max_line_width;
  const int day_h=clamp_int(s_settings.weekday_size,10,24);
  const int date_h=clamp_int(s_settings.date_size,10,24);
  const int day_natural=small_text_width(s_weekday,day_h);
  const int date_natural=small_text_width(s_monthday,date_h);
  const int space=5;
  int day_w=day_natural, date_w=date_natural;
  if (day_w+date_w+space>available) {
    // Horizontal fitting keeps independently chosen heights, avoids overlap,
    // and prevents the battery from covering larger weekday/date typography.
    const int fit=available-space;
    day_w=(day_natural*fit)/(day_natural+date_natural);
    date_w=fit-day_w;
  }
  const int total=day_w+space+date_w;
  const int start=mirrored?width-12-total:12;
  const int baseline=height-12;
  draw_small_text(ctx,s_weekday,start,baseline-day_h,day_h,day_w,s_settings.date_color);
  draw_small_text(ctx,s_monthday,start+day_w+space,baseline-date_h,
                  date_h,date_w,s_settings.date_color);
}

static GFont battery_font(int scale) {
  if (scale < 45) return fonts_get_system_font(FONT_KEY_GOTHIC_14);
  if (scale < 80) return fonts_get_system_font(FONT_KEY_GOTHIC_18);
  return fonts_get_system_font(FONT_KEY_GOTHIC_24);
}

static void render_text(GContext *ctx, const char *text, GFont font,
                        int x, int y, int w, int h, int32_t hex,
                        GTextAlignment align) {
  // Fixed, display-bounded rectangles: no width measurement and no overflow.
  if (!text || !font || w <= 0 || h <= 0) return;
  graphics_context_set_text_color(ctx, color(hex));
  graphics_draw_text(ctx, text, font, GRect(x, y, w, h),
                     GTextOverflowModeTrailingEllipsis, align, NULL);
}

static void update_time(void) {
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 110 time update begin");
  time_t now = time(NULL);
  struct tm *t = localtime(&now);
  if (!t) return;
  int h = t->tm_hour % 12;
  if (h == 0) h = 12;
  snprintf(s_hours, sizeof(s_hours), "%d", h);
  snprintf(s_minutes, sizeof(s_minutes), "%02d", t->tm_min);
  snprintf(s_single, sizeof(s_single), "%d:%02d", h, t->tm_min);
  strftime(s_weekday, sizeof(s_weekday), "%a", t);
  strftime(s_monthday, sizeof(s_monthday), "%b %d", t);
  for (unsigned int i = 0; s_weekday[i]; ++i)
    s_weekday[i] = (char)toupper((unsigned char)s_weekday[i]);
  for (unsigned int i = 0; s_monthday[i]; ++i)
    s_monthday[i] = (char)toupper((unsigned char)s_monthday[i]);
  snprintf(s_ampm, sizeof(s_ampm), "%s", t->tm_hour < 12 ? "AM" : "PM");
  if (s_canvas) layer_mark_dirty(s_canvas);
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 119 time update end");
}

static void battery_event(BatteryChargeState state) {
  s_battery = state;
  if (s_canvas) layer_mark_dirty(s_canvas);
}

static void minute_event(struct tm *tick_time, TimeUnits units_changed) {
  (void)tick_time;
  (void)units_changed;
  update_time();
}

// Battery percent and icon use the same fixed right edge at every size.
// Keeping the coordinate independent of icon width avoids the apparent
// right-hand blank gap when adjusting icon size.
static int battery_text_box_height(int scale) {
  return scale<45?19:(scale<80?23:29);
}

static void draw_battery(GContext *ctx, int width, int height) {
  APP_LOG(APP_LOG_LEVEL_INFO,
    "MPDIAG 220 battery draw start pos=%ld icon=%ld pct=%ld textsize=%ld iconsize=%ld",
    (long)s_settings.battery_position,(long)s_settings.battery_icon_visible,
    (long)s_settings.battery_percent_visible,(long)s_settings.battery_text_size,
    (long)s_settings.battery_icon_size);
  if (!s_settings.battery_enabled ||
      (!s_settings.battery_icon_visible && !s_settings.battery_percent_visible)) return;

  const int icon_scale=clamp_int(s_settings.battery_icon_size,30,100);
  const int text_scale=clamp_int(s_settings.battery_text_size,30,100);
  const int iw=7+icon_scale*15/100;
  const int ih=4+icon_scale*10/100;
  const bool mirrored=s_settings.mirror_layout!=0;
  const int right=width-10;
  const int icon_x=mirrored?10:right-iw;
  const bool top=s_settings.battery_position==0;
  const int th=battery_text_box_height(text_scale);
  // Gothic's metrics include top leading. A slightly overlapping layout box
  // places the visible percentage directly below the icon.
  const int pct_y=top?(s_settings.battery_icon_visible?9+ih-3:7)
                     :height-th-3;
  const int icon_y=top?9:(s_settings.battery_percent_visible?pct_y-ih+3:height-27);

  if(s_settings.battery_icon_visible) {
    graphics_context_set_stroke_color(ctx,color(s_settings.battery_icon_color));
    graphics_context_set_fill_color(ctx,color(s_settings.battery_icon_color));
    graphics_draw_rect(ctx,GRect(icon_x,icon_y,iw-3,ih));
    graphics_fill_rect(ctx,GRect(icon_x+iw-3,icon_y+ih/3,3,3),0,GCornerNone);
    const int fill_w=(iw-6)*clamp_int(s_battery.charge_percent,0,100)/100;
    if(fill_w>0 && ih>4) {
      graphics_fill_rect(ctx,GRect(icon_x+2,icon_y+2,fill_w,ih-4),0,GCornerNone);
    }
  }
  if(s_settings.battery_percent_visible) {
    char pct[6];
    snprintf(pct,sizeof(pct),"%d%%",clamp_int(s_battery.charge_percent,0,100));
    render_text(ctx,pct,battery_font(text_scale),mirrored?10:right-40,
                pct_y,40,th,s_settings.battery_text_color,
                mirrored?GTextAlignmentLeft:GTextAlignmentRight);
  }
}

static void canvas_update(Layer *layer, GContext *ctx) {
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 200 canvas start layout=%ld size=%ld",
    (long)s_settings.clock_layout, (long)s_settings.clock_size);
  const GRect bounds = layer_get_bounds(layer);
  const int width = bounds.size.w;
  const int height = bounds.size.h;
  const int scale = clamp_int(s_settings.clock_size, 50, 100);
  const bool is_single = s_settings.clock_layout == 1;
  const bool mirrored = s_settings.mirror_layout != 0;
  const bool top_battery = s_settings.battery_enabled &&
    s_settings.battery_position == 0 &&
    (s_settings.battery_icon_visible || s_settings.battery_percent_visible);

  graphics_context_set_fill_color(ctx, color(s_settings.background_color));
  graphics_fill_rect(ctx, bounds, 0, GCornerNone);

  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 205 clock draw start");
  if (is_single) {
    // Inline time expands until it reaches the 144-pixel screen's safe width.
    int digit_h = 31 + (scale - 50) * 18 / 50;
    int hours_w = 0;
    int minutes_w = 0;
    int total_w = 0;
    do {
      hours_w = clock_digits_width(s_hours, true, digit_h);
      minutes_w = clock_digits_width(s_minutes, false, digit_h);
      total_w = hours_w + minutes_w + 13;
      if (total_w <= width - 24 || digit_h <= 25) break;
      --digit_h;
    } while (true);
    const int x = mirrored ? width-12-total_w : 12;
    const int y = top_battery ? 47 : 34;
    draw_clock_digits(ctx, s_hours, true, x, y, digit_h, s_settings.hours_color, 0);
    const int colon_x = x + hours_w + 5;
    const int dot_size = digit_h >= 40 ? 4 : 3;
    graphics_context_set_fill_color(ctx, color(s_settings.hours_color));
    graphics_fill_rect(ctx, GRect(colon_x, y + digit_h / 3, dot_size, dot_size), 0, GCornerNone);
    graphics_fill_rect(ctx, GRect(colon_x, y + digit_h * 2 / 3, dot_size, dot_size), 0, GCornerNone);
    draw_clock_digits(ctx, s_minutes, false, colon_x + 8, y, digit_h,
                      s_settings.minutes_color, 0);
    if (s_settings.show_ampm) {
      render_text(ctx, s_ampm, fonts_get_system_font(FONT_KEY_GOTHIC_14),
                  mirrored ? 12 : width-38, y + digit_h + 6, 29, 21,
                  s_settings.ampm_color,
                  mirrored ? GTextAlignmentLeft : GTextAlignmentRight);
    }
  } else {
    // Both rows share the same height. If hours are two digits, normalize
    // both rows to the same total width, keeping the heavy/light distinction.
    // Single-digit hours retain their natural narrow silhouette.
    const int digit_h = 36 + (scale - 50) * 22 / 50;
    const int y = scale >= 72 ? 20 - (scale - 72) * 16 / 28
                              : 20 + (72 - scale) * 5 / 22;
    const int minutes_y = y + digit_h - 1;
    const int hours_w = clock_digits_width(s_hours, true, digit_h);
    const int natural_minutes_w = clock_digits_width(s_minutes, false, digit_h);
    const bool two_digit_hour = s_hours[0] && s_hours[1] && !s_hours[2];
    const int fitted_width = two_digit_hour
      ? clamp_int(hours_w > natural_minutes_w ? hours_w : natural_minutes_w,
                  1, s_settings.show_ampm ? width - 53 : width - 24)
      : 0;
    const int hours_actual = fitted_width > 0 ? fitted_width : hours_w;
    const int minutes_actual = fitted_width > 0 ? fitted_width : natural_minutes_w;
    const int hours_x = mirrored ? width-12-hours_actual : 12;
    const int minutes_x = mirrored ? width-12-minutes_actual : 12;
    draw_clock_digits(ctx, s_hours, true, hours_x, y, digit_h,
                      s_settings.hours_color, fitted_width);
    draw_clock_digits(ctx, s_minutes, false, minutes_x,
                      minutes_y, digit_h, s_settings.minutes_color, fitted_width);
    if (s_settings.show_ampm) {
      const int am_x = mirrored ? minutes_x-36 : minutes_x+minutes_actual+5;
      render_text(ctx, s_ampm, fonts_get_system_font(FONT_KEY_GOTHIC_14),
                  am_x, minutes_y + digit_h - 19, 31, 21,
                  s_settings.ampm_color, GTextAlignmentLeft);
    }
  }
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 209 clock draw end");

  const int accent_width=clamp_int(s_settings.accent_width,8,width-24);
  graphics_context_set_fill_color(ctx, color(s_settings.accent_color));
  graphics_fill_rect(ctx, GRect(mirrored?width-12-accent_width:12,
                                height-44,accent_width,3),0,GCornerNone);
  draw_date_row(ctx,width,height);
  draw_battery(ctx,width,height);
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 229 canvas end");
}

static bool parse_setting_bytes(uint8_t type, const uint8_t *data,
                                uint16_t len, int32_t *out) {
  if (!data || !out) return false;

  if (type == TUPLE_UINT || type == TUPLE_INT) {
    if (len != 1 && len != 2 && len != 4) return false;
    uint32_t bits = 0;
    for (uint16_t i = 0; i < len; ++i) {
      bits |= ((uint32_t)data[i]) << (8 * i);
    }
    if (type == TUPLE_INT && len < 4 && (data[len - 1] & 0x80)) {
      bits |= 0xFFFFFFFFUL << (8 * len);
    }
    *out = (int32_t)bits;
    return true;
  }

  if (type != TUPLE_CSTRING || len < 2 || len > 24 || data[len - 1] != 0) {
    return false;
  }
  // Match the exact bytes, including the required final NUL.
  if (len == 5 && data[0] == 't' && data[1] == 'r' &&
      data[2] == 'u' && data[3] == 'e') {
    *out = 1;
    return true;
  }
  if (len == 6 && data[0] == 'f' && data[1] == 'a' &&
      data[2] == 'l' && data[3] == 's' && data[4] == 'e') {
    *out = 0;
    return true;
  }

  uint16_t i = 0;
  uint32_t base = 10;
  bool negative = false;
  if (data[i] == '#') {
    base = 16;
    ++i;
  } else if (len > 3 && data[0] == '0' &&
             (data[1] == 'x' || data[1] == 'X')) {
    base = 16;
    i = 2;
  } else if (data[i] == '-' || data[i] == '+') {
    negative = data[i] == '-';
    ++i;
  }
  if (i >= len - 1) return false; // No digits.

  uint32_t value = 0;
  for (; i < len - 1; ++i) {
    uint8_t c = data[i];
    uint32_t digit;
    if (c >= '0' && c <= '9') digit = (uint32_t)(c - '0');
    else if (c >= 'a' && c <= 'f') digit = (uint32_t)(c - 'a' + 10);
    else if (c >= 'A' && c <= 'F') digit = (uint32_t)(c - 'A' + 10);
    else return false;
    if (digit >= base || value > (UINT32_MAX - digit) / base) return false;
    value = value * base + digit;
  }
  if (negative) {
    if (value > (uint32_t)INT32_MAX + 1UL) return false;
    *out = (value == (uint32_t)INT32_MAX + 1UL) ? INT32_MIN : -(int32_t)value;
  } else {
    if (base == 10 && value > INT32_MAX) return false;
    *out = (int32_t)value;
  }
  return true;
}

static bool parse_setting_number(const Tuple *tuple, int32_t *out) {
  if (!tuple || !out) return false;
  return parse_setting_bytes((uint8_t)tuple->type, tuple->value->data,
                             tuple->length, out);
}

// Use only one dictionary traversal per incoming message; this also keeps
// diagnostics tied to the precise field being processed.
static void message_received(DictionaryIterator *iter, void *context) {
  (void)context;
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 300 inbox begin");
  if (!iter) {
    APP_LOG(APP_LOG_LEVEL_ERROR, "MPDIAG 301 null inbox");
    return;
  }

  FaceSettings next = s_settings;
  unsigned int accepted = 0;
  unsigned int inspected = 0;
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 301 reading first tuple");
  Tuple *tuple = dict_read_first(iter);
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 302 first tuple ready");
  while (tuple && inspected < 32) {
    ++inspected;
    APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 303 tuple key=%lu type=%u len=%u",
            (unsigned long)tuple->key, (unsigned)tuple->type,
            (unsigned)tuple->length);
    int32_t value = 0;
    APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 304 parse begin key=%lu",
            (unsigned long)tuple->key);
    bool parsed = parse_setting_number(tuple, &value);
    APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 304 parse end ok=%d value=%ld",
            parsed ? 1 : 0, (long)value);
    if (parsed) {
      bool recognized = true;
      if (tuple->key == MESSAGE_KEY_ClockLayout) { next.clock_layout = clamp_int(value, 0, 1); }
      else if (tuple->key == MESSAGE_KEY_ClockSize) { next.clock_size = clamp_int(value, 50, 100); }
      else if (tuple->key == MESSAGE_KEY_ShowAmPm) { next.show_ampm = clamp_int(value, 0, 1); }
      else if (tuple->key == MESSAGE_KEY_BatteryEnabled) { next.battery_enabled = clamp_int(value, 0, 1); }
      else if (tuple->key == MESSAGE_KEY_BatteryPosition) {
        next.battery_position = clamp_int(value, 0, 1);
        APP_LOG(APP_LOG_LEVEL_INFO,"MPDIAG 325 moving battery: text size=%ld icon size=%ld",
                (long)next.battery_text_size,(long)next.battery_icon_size);
      }
      else if (tuple->key == MESSAGE_KEY_BatteryIconVisible) { next.battery_icon_visible = clamp_int(value, 0, 1); }
      else if (tuple->key == MESSAGE_KEY_BatteryPercentVisible) { next.battery_percent_visible = clamp_int(value, 0, 1); }
      else if (tuple->key == MESSAGE_KEY_BatteryIconSize) { next.battery_icon_size = clamp_int(value, 30, 100); }
      else if (tuple->key == MESSAGE_KEY_BatteryTextSize) {
        next.battery_text_size = clamp_int(value, 30, 100);
        APP_LOG(APP_LOG_LEVEL_INFO,"MPDIAG 326 battery text size received=%ld stored=%ld",
                (long)value,(long)next.battery_text_size);
      }
      else if (tuple->key == MESSAGE_KEY_BackgroundColor) { next.background_color = value & 0xFFFFFF; }
      else if (tuple->key == MESSAGE_KEY_HoursColor) { next.hours_color = value & 0xFFFFFF; }
      else if (tuple->key == MESSAGE_KEY_MinutesColor) { next.minutes_color = value & 0xFFFFFF; }
      else if (tuple->key == MESSAGE_KEY_AmPmColor) { next.ampm_color = value & 0xFFFFFF; }
      else if (tuple->key == MESSAGE_KEY_AccentColor) { next.accent_color = value & 0xFFFFFF; }
      else if (tuple->key == MESSAGE_KEY_DateColor) { next.date_color = value & 0xFFFFFF; }
      else if (tuple->key == MESSAGE_KEY_BatteryIconColor) { next.battery_icon_color = value & 0xFFFFFF; }
      else if (tuple->key == MESSAGE_KEY_BatteryTextColor) { next.battery_text_color = value & 0xFFFFFF; }
      else if (tuple->key == MESSAGE_KEY_AccentWidth) { next.accent_width = clamp_int(value, 8, 120); }
      else if (tuple->key == MESSAGE_KEY_WeekdaySize) { next.weekday_size = clamp_int(value, 10, 24); }
      else if (tuple->key == MESSAGE_KEY_DateSize) { next.date_size = clamp_int(value, 10, 24); }
      else if (tuple->key == MESSAGE_KEY_MirrorLayout) { next.mirror_layout = clamp_int(value, 0, 1); }
      else {
        recognized = false;
        APP_LOG(APP_LOG_LEVEL_WARNING, "MPDIAG 304 unknown key=%lu", (unsigned long)tuple->key);
      }
      if (recognized) {
        ++accepted;
        APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 305 accepted key=%lu value=%ld",
                (unsigned long)tuple->key, (long)value);
      }
    } else {
      APP_LOG(APP_LOG_LEVEL_WARNING, "MPDIAG 306 rejected key=%lu", (unsigned long)tuple->key);
    }
    tuple = dict_read_next(iter);
  }
  if (tuple) APP_LOG(APP_LOG_LEVEL_WARNING, "MPDIAG 307 tuple limit reached");
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 310 inbox parsed accepted=%u inspected=%u", accepted, inspected);
  if (!accepted || memcmp(&s_settings, &next, sizeof(next)) == 0) return;

  next.version = SETTINGS_VERSION;
  s_settings = next;
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 320 persist begin");
  const int written = persist_write_data(SETTINGS_KEY, &s_settings, sizeof(s_settings));
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 329 persist result=%d", written);
  if (written != (int)sizeof(s_settings)) {
    APP_LOG(APP_LOG_LEVEL_WARNING, "Settings persistence failed: %d", written);
  }
  if (s_canvas) layer_mark_dirty(s_canvas);
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 339 applied layout=%ld size=%ld pos=%ld textsize=%ld iconsize=%ld",
          (long)s_settings.clock_layout, (long)s_settings.clock_size,
          (long)s_settings.battery_position,(long)s_settings.battery_text_size,
          (long)s_settings.battery_icon_size);
}

static void message_dropped(AppMessageResult reason, void *context) {
  (void)context;
  APP_LOG(APP_LOG_LEVEL_WARNING, "Settings AppMessage dropped: %d", (int)reason);
}

static void window_load(Window *window) {
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 040 window load begin");
  Layer *root = window_get_root_layer(window);
  s_canvas = layer_create(layer_get_bounds(root));
  layer_set_update_proc(s_canvas, canvas_update);
  layer_add_child(root, s_canvas);
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 049 window layer installed");
  update_time();
}

static void window_unload(Window *window) {
  (void)window;
  layer_destroy(s_canvas);
  s_canvas = NULL;
}

static void init(void) {
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 000 init begin version 1.0.10 mirror/date controls");
  load_settings();
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 019 settings loaded");
  s_battery = battery_state_service_peek();
  s_window = window_create();
  window_set_window_handlers(s_window, (WindowHandlers) {
    .load = window_load,
    .unload = window_unload
  });
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 050 push window");
  window_stack_push(s_window, true);
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 059 window pushed");
  tick_timer_service_subscribe(MINUTE_UNIT, minute_event);
  battery_state_service_subscribe(battery_event);
  app_message_register_inbox_received(message_received);
  app_message_register_inbox_dropped(message_dropped);
  // Clay sends 21 keys; 768 bytes provides headroom for color strings.
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 060 opening inbox");
  AppMessageResult message_status = app_message_open(768, 128);
  if (message_status != APP_MSG_OK) {
    APP_LOG(APP_LOG_LEVEL_ERROR, "AppMessage initialization failed: %d", (int)message_status);
  }
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 069 inbox status=%d", (int)message_status);
  update_time();
  APP_LOG(APP_LOG_LEVEL_INFO, "MPDIAG 099 init complete");
}

static void deinit(void) {
  tick_timer_service_unsubscribe();
  battery_state_service_unsubscribe();
  app_message_deregister_callbacks();
  window_destroy(s_window);
}

int main(void) {
  init();
  app_event_loop();
  deinit();
  return 0;
}
